"""Rendered interactive-board and beginner-practice acceptance, synthetic library."""
import json
import os
from pathlib import Path
from uuid import uuid4
from playwright.sync_api import sync_playwright,expect

root=os.environ.get('WEB_URL','http://web:8080');artifacts=Path('/artifacts');artifacts.mkdir(parents=True,exist_ok=True)
errors=[];checks=[]
with sync_playwright() as p:
    browser=p.chromium.launch();context=browser.new_context(viewport={'width':1440,'height':1100});page=context.new_page()
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.goto(root+'/#personal',wait_until='networkidle');page.locator('#study-signup-tab').click()
    page.locator('#study-auth-form input[name=username]').fill('BoardDemo'+uuid4().hex[:8])
    page.locator('#study-auth-form input[name=password]').fill('valid-board-demo-password');page.locator('#study-auth-submit').click()
    expect(page.locator('#study-home')).to_be_visible();page.get_by_role('link',name='Import my games').click()
    page.locator('#study-import-form input[name=file]').set_input_files('/fixtures/personal-demo.pgn');page.locator('#study-import-submit').click()
    expect(page.locator('#study-games-section')).to_be_visible(timeout=60000)
    page.locator('[data-study-tab=overview]').click()
    expect(page.locator('#study-metrics .metric strong').first).to_have_text('24',timeout=60000)
    page.locator('#study-findings a').first.click();expect(page.locator('#study-game-page')).to_be_visible()
    page.locator('#study-start').click();expect(page.locator('#study-board svg')).to_have_count(32)
    page.locator('.board-options summary').click();page.locator('#board-preferences select[name=theme]').select_option('slate')
    page.locator('#board-preferences select[name=orientation]').select_option('white')
    page.locator('#board-preferences button').click();expect(page.locator('#board-settings-status')).to_contain_text('Saved')
    expect(page.locator('#study-board')).to_have_attribute('data-theme','slate')
    page.locator('#study-board [data-square=a1]').focus();page.keyboard.press('ArrowUp')
    expect(page.locator('#study-board [data-square=a2]')).to_be_focused()
    page.locator('#study-board [data-square=e2]').click();expect(page.locator('#study-board [data-square=e4]')).to_have_class(__import__('re').compile('legal-target'))
    page.locator('#study-board [data-square=e4]').click();expect(page.locator('#study-trial-line')).to_contain_text('e4')
    page.locator('#study-board [data-square=e7]').click();expect(page.locator('#study-board [data-square=e5]')).to_have_class(__import__('re').compile('legal-target'))
    page.locator('#study-board [data-square=e5]').click();expect(page.locator('#study-trial-line')).to_contain_text('e4 e5')
    page.locator('#study-variation-save input').fill('Synthetic center line');page.locator('#study-variation-save button').click()
    expect(page.locator('#study-saved-variations')).to_contain_text('Synthetic center line')
    page.locator('#study-trial-undo').click();expect(page.locator('#study-trial-line')).to_have_text('Trial: e4')
    page.locator('#study-position-profile').select_option('quick');page.locator('#study-position-analyze').click()
    expect(page.locator('#study-position-engine')).to_contain_text('Position search: complete',timeout=60000)
    page.locator('#study-flip').click();expect(page.locator('#study-position-engine')).to_contain_text('Position search: complete')
    page.locator('#study-trial-reset').click();expect(page.locator('#study-trial')).to_be_hidden()
    page.reload(wait_until='networkidle');expect(page.locator('#study-board')).to_have_attribute('data-theme','slate')
    page.locator('#study-saved-variations button').filter(has_text='Synthetic center line').click()
    expect(page.locator('#study-trial-line')).to_have_text('Trial: e4 e5')
    page.locator('#study-flip').click();expect(page.locator('#study-trial-line')).to_have_text('Trial: e4 e5')
    page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(artifacts/'board-configurable-desktop.png'),full_page=True)
    checks.append('SVG pieces, account preferences, legal trials, undo, saved variation, flip and bounded real position search')
    page.locator('[data-view=learn]').click();expect(page.locator('#lesson-heading')).to_contain_text('Give your pieces room')
    expect(page.locator('#lesson-menu button')).to_have_count(7)
    page.locator('#lesson-board [data-square=e2]').click();expect(page.locator('#lesson-board [data-square=e4]')).to_have_class(__import__('re').compile('legal-target'))
    page.locator('#lesson-board [data-square=e4]').click();expect(page.locator('#lesson-feedback')).to_contain_text('Goal met')
    expect(page.locator('#lesson-progress')).to_contain_text('1 saved attempt')
    page.locator('#learn-source').select_option('personal');expect(page.locator('#learn-source-note')).to_contain_text('24 example games')
    expect(page.locator('#learn-example')).to_contain_text('Your game');expect(page.locator('#learn-example svg')).to_have_count(32)
    page.locator('#learn-example').get_by_role('button',name='Reveal the recorded move').click();expect(page.locator('#learn-example')).to_contain_text('Recorded:')
    expect(page.locator('#learn-focus')).to_contain_text('Revisit a familiar opening')
    page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(artifacts/'learn-personal-desktop.png'),full_page=True)
    page.locator('#lesson-menu button[data-lesson=middlegame-plan]').click()
    expect(page.locator('#lesson-heading')).to_contain_text('Choose a plan')
    page.locator('#lesson-board [data-square=f1]').click();expect(page.locator('#lesson-board [data-square=e1]')).to_have_class(__import__('re').compile('legal-target'))
    page.locator('#lesson-board [data-square=e1]').click();expect(page.locator('#lesson-feedback')).to_contain_text('Goal met')
    page.locator('#lesson-menu button[data-lesson=endgame-promotion]').click()
    page.locator('#lesson-board [data-square=a7]').click();expect(page.locator('#lesson-board [data-square=a8]')).to_have_class(__import__('re').compile('legal-target'))
    page.locator('#lesson-board [data-square=a8]').click();expect(page.locator('.promotion-picker button')).to_have_count(4)
    page.get_by_role('button',name='Promote to queen').click();expect(page.locator('#lesson-feedback')).to_contain_text('Goal met')
    page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth'),'mobile overflow'
    page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(artifacts/'learn-mobile.png'),full_page=True)
    checks.append('seven lessons, computed drill grading, persisted progress, own-library evidence, promotion picker and mobile layout')
    guest=browser.new_context();g=guest.new_page();g.goto(root+'/#learn',wait_until='networkidle')
    expect(g.locator('#lesson-progress')).to_contain_text('Guest practice');expect(g.locator('#lesson-menu button')).to_have_count(7)
    g.locator('#lesson-board [data-square=e2]').click();expect(g.locator('#lesson-board [data-square=e4]')).to_have_class(__import__('re').compile('legal-target'))
    g.locator('#lesson-board [data-square=e4]').click();expect(g.locator('#lesson-feedback')).to_contain_text('Goal met')
    checks.append('guest practice without private-service authentication')
    assert not errors,errors
    browser.close()
(artifacts/'practice-acceptance.json').write_text(json.dumps({'status':'passed','source':'Synthetic DemoStudent library; original foundation drills','checks':checks,'javascript_errors':errors},indent=2)+'\n')
print('Board/learning acceptance passed:',len(checks),'scenario groups')
